def test_list_pipelines_pagination_with_next_page_token(
    api_client,
    default_headers: Dict[str, str],
    endpoint: str,
    method: str,
    spec_validator: SwaggerSchemaValidator,
    endpoint_test_data: List[Dict[str, Any]],
    config_test_data: Dict[str, Any],
):
    """
    Validates pagination link by following next_page_token when present.
    Uses response-derived token (no hardcoding). If no token present or non-200,
    the iteration simply moves on.
    """
    for scenario in endpoint_test_data:
        # Build params including optional scenario values
        params = build_query_params_from_config_and_scenario(
            config_test_data=config_test_data,
            scenario=scenario,
            include_optional=True,
        )

