        # Validate first response schema regardless of status
        assert_schema_validation(spec_validator, endpoint, method, first)

        if first.status_code != 200:
            # Cannot paginate if initial request was not successful per spec
            continue

        data = _safe_parse_json(first)
        if not isinstance(data, dict):
            # If the body isn't JSON dict, we cannot proceed with token-based pagination
            continue

        next_token = data.get("next_page_token")
        if not next_token:
            # No pagination available, proceed to next scenario
            continue

        # Follow the link using the next_page_token
        follow_params = dict(params)
        follow_params["page-token"] = next_token  # override with response-derived token

        second = api_client.get(endpoint, headers=default_headers, params=follow_params)
        # Expect a 200 here generally, but do not hardcode; validate schema by response code.
        assert_schema_validation(spec_validator, endpoint, method, second)
